    slug: "alaska-labrie-tax-preparer-covid-relief-identity-theft-fraud",
    description:
      "Cheryl Labrie, 39, owned AKBS LLC — operating a Liberty Tax Service franchise and a bookkeeping practice called Alaska's Bookkeeping Solutions — providing tax preparation and bookkeeping services to Anchorage-area businesses, including several licensed marijuana companies. Between April 2020 and November 2021, prosecutors say Labrie used the stolen identities of at least seven employees from her own client businesses, together with falsified IRS records, to submit fraudulent applications to the Small Business Administration's Paycheck Protection Program and Economic Injury Disaster Loan program, ultimately obtaining nearly $970,000 in pandemic relief funds meant for struggling small businesses. Rather than passing the money to the businesses or employees named on the applications, she spent it on a hillside property, a home down payment, and payments toward an unrelated prior restitution obligation. A federal grand jury indicted Labrie in January 2024, with superseding indictments in March 2025 and February 2026 eventually charging her with seven counts of aggravated identity theft, six counts of wire fraud, and two counts of money laundering; she pleaded guilty to one count each of wire fraud and aggravated identity theft in April 2026. She was sentenced on August 24, 2026 to three years and ten months in federal prison plus three years of supervised release, and ordered to repay the full $970,000 in restitution. \"Ms. Labrie orchestrated an elaborate web of deceit to steal nearly $1 million from American taxpayers, funds that could have benefited struggling businesses during a national emergency,\" said U.S. Attorney Michael J. Heyman. Business owners who rely on a third-party bookkeeper or tax preparer with access to employee Social Security numbers should periodically check whether any loans, credit accounts, or federal benefit applications have been opened in an employee's name without that employee's knowledge, since abuse of that kind of insider access can otherwise go undetected for years.",
