    description:
      "Between August and September 2025, Christian Pacheco, 31, of Perth Amboy, New Jersey, made 28 separate visits to Home Depot stores across Delaware, telling cashiers each time that he had forgotten his store credit card and instead reciting a legitimate cardholder's Social Security number to look the account up manually — then backing up the claim with a fraudulent identification card that carried his own photo but a victim's name and personal information. The scheme, using the stolen identities of multiple different cardholders including at least one victim over 62, netted more than $24,000 in fraudulent merchandise before a Home Depot corporate investigator flagged the pattern of visits and referred it to the Delaware State Police Troop 2 Financial Crimes Unit in October 2025. Detectives traced the purchases back to Pacheco, who was taken into custody at a New Jersey airport on January 5, 2026 and extradited to Delaware, where he was charged with 28 counts of felony identity theft, 28 counts of second-degree forgery, 19 counts of unlawful use of a payment card belonging to a victim 62 or older, six counts of second-degree conspiracy, and dozens of related theft counts, before posting a $63,750 cash bond. The case is a reminder that identity theft doesn't require a computer or a stolen card in hand — a memorized Social Security number and a convincing fake ID were enough to walk out of two dozen stores with merchandise billed to strangers, which is why regularly reviewing store and credit card statements for unfamiliar purchases remains one of the few ways such slow-building schemes get caught.",
