    description:
      "Arizona Attorney General Kris Mayes's office received more than 1,500 consumer complaints between 2013 and 2023 against Choice Home Warranty, a New Jersey-based service-contract company, alleging that it took monthly premiums for home warranty plans but then refused to replace air conditioning units and other major appliances the company had advertised as covered once a claim was actually filed. The office's 2019 consumer fraud lawsuit alleged the company manipulated coverage-term language and buried critical exclusions in fine print that Arizona families, seniors, and veterans had no realistic way to spot before paying for a plan. A consent judgment entered January 23, 2026 resolved the case with an $11.8 million settlement — which Mayes called the largest of its kind in Arizona history — while Choice Home Warranty denied wrongdoing; the judgment requires the company to reform its sales practices and make meaningful upfront disclosures about exactly what is and isn't covered before a consumer hands over payment information. Consumers who purchased a Choice Home Warranty plan over the phone for an Arizona property between January 1, 2013 and January 1, 2023 may be eligible for restitution through the claims process the Attorney General's office opened following the settlement. \"Businesses cannot hide behind fine print and hidden disclosures to exploit our vulnerable consumers,\" Mayes said in announcing the judgment. Before buying any home warranty, consumers should read the full contract for exclusions on big-ticket items like HVAC systems, water heaters, and plumbing before paying, ask the seller to confirm specific coverage in writing, and report a company that refuses to honor an advertised repair or replacement to the Arizona Attorney General's Consumer Information and Complaints Unit.",
