      "GS Labs, a COVID-19 rapid-testing business founded by medical diagnostics company 88Med, advertised inflated cash prices — as high as $380 per test and nearly $1,000 for multi-panel tests — specifically to secure higher reimbursement from insurers and cash-paying consumers, while separately marketing \"no out-of-pocket expenses\" for insured patients who were then hit with an undisclosed $49 administrative fee per test. The company also guaranteed results within three days, but hundreds of thousands of consumers waited well over a week for results that were, by then, essentially useless for the purpose they'd been ordered for, without ever receiving a refund or discount for the delay. Colorado Attorney General Phil Weiser and a bipartisan coalition of 18 other state attorneys general announced a $4.87 million settlement on June 10, 2026, resolving allegations that GS Labs' pricing and marketing practices violated the Colorado Consumer Protection Act; the company will pay more than $3.6 million directly to affected consumers as restitution and $1.25 million to the participating states, with Colorado receiving $23,601 toward legal costs. \"Preying on Coloradans is never tolerated, and to do so during such a uniquely difficult period is unconscionable,\" Weiser said. \"Our office will continue to hold bad actors accountable for such practices.\" GS Labs has since stopped offering COVID-19 rapid testing, and the settlement bars the company from charging undisclosed administrative fees, pricing above the market rate, or billing for late results if it resumes. Consumers evaluating any medical testing service's advertised price and turnaround guarantee should get both in writing and check whether a \"no out-of-pocket\" promise excludes separate administrative or processing fees before agreeing to be tested.",
