      "A Southern California hospice fraud ring purchased the personal identifying information of non-California residents on the dark web, used those stolen identities to fraudulently enroll the victims in Medi-Cal, and then installed \"straw owners\" atop 14 shell hospice companies that billed the state for end-of-life care that was never provided to anyone. California Attorney General Rob Bonta, working with the California Department of Health Care Services and the California Department of Justice, announced on April 9, 2026 that the operation — dubbed \"Operation Skip Trace\" — had charged 21 suspects in connection with $267 million in fraudulent hospice billing, calling it a \"brazen, calculated scheme\" in which \"not a single legitimate hospice service was ever provided.\" On April 8, 2026, investigators executed search and arrest warrants at twelve locations across Southern California, arresting five suspects and seizing two handguns and more than $757,000 in cash. Defendants face charges including conspiracy to commit health care fraud, health care fraud, money laundering, and identity theft, with aggravated white-collar-crime and aggravated money-laundering enhancements attached given the scale of the loss. The case illustrates how hospice fraud can be committed entirely with stolen identities rather than real patients, meaning a Medi-Cal beneficiary might discover the fraud only after receiving a benefits statement listing hospice services under their name that they never received and never authorized. Californians who spot an unfamiliar hospice or home-health provider on a Medi-Cal or Medicare statement are urged to report it immediately to the California Department of Justice's Bureau of Medi-Cal Fraud and Elder Abuse rather than assume it is a clerical error.",
