      "In July 2025, a Manatee County resident grew suspicious after a caller claiming to be with the Federal Trade Commission warned him he would miss jury duty and face arrest unless he paid a fine immediately; when a courier arrived at his home to collect cash, he photographed her and her car and called the Manatee County Sheriff's Office, unraveling a criminal network that had already stolen more than $3.5 million from at least 40 victims statewide. Investigators say callers posing as FTC or FBI agents combined fabricated jury-duty warrants, threats of imminent arrest, and fake iCloud payment alerts to panic elderly victims into believing they owed money immediately, then directed them to withdraw cash or buy cryptocurrency and hand it to a courier — often an unwitting rideshare driver or a paid pickup runner — rather than wiring funds through a bank that might flag the transaction. Xin Liu, 40, of Apopka, drove to at least six locations around the state between July 22 and July 30, 2025, including a Gainesville assisted-living community, collecting more than $95,000 in a single week before detectives traced her through the photographed license plate; she was sentenced to 27 months in federal prison for scheme to defraud. Two additional couriers, ages 52 and 56, were later arrested on related scheme-to-defraud and conspiracy charges as the investigation continued. \"Take that pause, hang up the phone... Do verification first. Contact family, law enforcement,\" Manatee County Sheriff's Office Detective Gary Cummings advised, noting that no legitimate government agency demands cash, gift cards, or cryptocurrency handed to a stranger at your door to avoid arrest.",
