    slug: 'arizona-cryptocurrency-atm-scam',
    description: `Arizona Attorney General Kris Mayes issued a consumer alert on February 2, 2026, warning residents about a rapidly growing scam built around cryptocurrency ATMs — kiosks that let a user insert cash and convert it directly into digital currency, found in gas stations, convenience stores, and strip malls across the state. Scammers first make contact by phone, email, or text under a false pretense — impersonating a loved one in trouble, a law enforcement officer serving a warrant, a utility company threatening shutoff, or a bank flagging a "compromised" account — and use that manufactured emergency to push the victim into urgent action. Once panicked, the victim is directed to withdraw cash, drive to the nearest cryptocurrency ATM, and deposit it while scanning a QR code that routes the funds straight into a wallet the scammer controls; because the transaction settles on the blockchain almost immediately, it cannot be reversed and is extraordinarily difficult to trace, unlike a disputed wire transfer or credit card charge. Mayes's office noted that older adults bear the brunt of this scheme: more than two-thirds of cryptocurrency ATM fraud victims in 2024 were over age 60, and Arizonans lost more than $177 million in savings to this type of fraud that year alone. Alongside the alert, the Attorney General's Office launched a dedicated fraud complaint form and highlighted Arizona's HB2387, which gives victims who report a qualifying cryptocurrency ATM loss within 30 days a chance at recovering funds. The office's core advice: no legitimate government agency, bank, or utility will ever instruct someone to resolve a debt, fine, or "emergency" by depositing cash into a cryptocurrency kiosk, and anyone told to do so should stop, hang up, and independently verify the situation before moving any money. Arizonans who believe they've encountered this scam are urged to file a complaint at azag.gov or call the Attorney General's Consumer Protection office.`,
