    sources: ["U.S. Department of Justice, Tax Division", 'Internal Revenue Service Criminal Investigation', 'WBRC'],
    sourceUrl: 'https://www.justice.gov/opa/pr/alabama-man-charged-preparing-false-tax-returns',
