    slug: 'arizona-boateng-ghana-romance-inheritance-fraud-ring',
    description: `Joseph Kwadwo Badu Boateng, a Ghanaian national who performed and marketed himself online as an entertainer under the name "Dada Joe Remix," pleaded guilty on June 30, 2026 in federal court in Arizona to conspiracy to commit wire fraud for his role in a romance-and-inheritance scheme that ran from 2013 to March 2023 and defrauded victims across Arizona and the rest of the country out of a combined $4.4 million. Prosecutors said Boateng and his co-conspirators built fake identities on dating apps and through text messages, posing as romantic partners to build trust with victims — including at least one elderly Arizona resident — before claiming they had access to a stash of gold and jewels through a foreign inheritance that they were willing to share, provided the victim first wired money to cover supposed taxes, customs duties, and release fees. Court records identify at least 18 victims with individual losses ranging from $12,000 to $1.5 million each. Boateng was arrested in Ghana on May 28, 2026 and extradited to the United States the following month to face prosecution, with sentencing scheduled for September 2026 and $4.4 million in restitution already agreed to as part of his plea. The case is part of a broader pattern of romance-and-inheritance rings run from West Africa that combine a manufactured romantic relationship with a supposed windfall — gold, jewels, a lottery prize, or a deceased relative's estate — that always requires the victim to send money first; anyone contacted online by a romantic interest who later claims to need help unlocking an inheritance, gold shipment, or prize should stop sending money immediately and verify the person's identity independently before any further contact.`,
