UsAF.push({
    name: 'Connecticut Storm-Chaser Roofing Scam Alert',
    slug: 'connecticut-storm-chaser-roofing-scam-alert',
    description: `The Connecticut Department of Consumer Protection (DCP), joined by the Better Business Bureau, issued a consumer alert on July 14, 2025 warning homeowners about "storm chaser" roofing crews that follow severe weather into neighborhoods and go door to door offering fast repairs. According to DCP, the crews often claim to have spotted damage on a homeowner's roof while working next door, offer a free inspection to get onto the property, and then use high-pressure tactics — urgency, a limited-time discount, or a claim that other neighbors have already signed up — to push a same-visit contract signature. Some pressure homeowners to pad the total contract price above the actual cost of repairs so the difference can be used to cover their insurance deductible, which is itself illegal in Connecticut. DCP said it fielded 91 roofing-related complaints in just the first half of 2025, after logging 285 for all of 2024 and 247 in 2023 — a steady upward trend the agency tied directly to increasingly severe spring storms. "Summer is a common time for door-to-door sales, but homeowners should be aware of potential scams," said DCP Commissioner Bryan T. Cafferelli, while BBB spokeswoman Kristen Johnson added, "Any reputable company will want to give you the time to do your research and see that it is trustworthy." Every roofer and home-improvement contractor doing business in Connecticut is legally required to hold an active Home Improvement Contractor registration, which homeowners can verify through the state's eLicense lookup before signing anything; the alert also reminds residents that Connecticut law gives them three business days to cancel a home-improvement contract signed at their home, and that a written contract, a local business address, and proof of insurance are basic requirements a legitimate roofer will have no trouble providing.`,
    categorySlug: 'home-improvement-solar',
    alertLevel: 'medium',
    sources: ['Connecticut Department of Consumer Protection', 'Better Business Bureau'],
    sourceUrl: 'https://portal.ct.gov/dcp/news-releases-from-the-department-of-consumer-protection/2025-news-releases/be-aware-of-scammers-posing-as-roofing-companies',
    country: 'US',
    state: 'CT',
});

UsAF.push({
    name: 'Los Angeles Stolen-Identity Elderly Homeowner Loan Fraud Ring',
    slug: 'california-los-angeles-elderly-homeowner-stolen-identity-loan-fraud',
    description: `Federal prosecutors say that from January 2021 to May 2023, an eleven-person ring led by Nazaret Chakrian and Arnold Moradians targeted elderly homeowners in Santa Monica and the Los Angeles neighborhoods of Hollywood, Hollywood Hills, Westwood, and Chinatown — many of whom owned their homes outright, meaning there was no existing mortgage statement that would tip them off when a new one appeared. Ring members stole victims' personal identifying information, and Chakrian and co-defendant Craig Higdon used it to manufacture counterfeit government identification documents in the victims' names, while Cynthia Borjas and Avetis Hekimyan created fraudulent email accounts to impersonate the victims online. Using the stolen identities, fake IDs, and impostor email accounts, Chakrian, Moradians, Hekimyan, Armen Vardevaryan, and Helen Spangler then posed as the homeowners themselves or as their agents, brokers, or relatives and submitted fraudulent "hard money" loan applications to private lenders, falsely representing that the loans would be secured by the victims' properties and backing the paperwork with forged bank statements, rental agreements, and even fabricated death certificates. The scheme sought $17.4 million in fraudulent loans and is alleged to have actually extracted roughly $6 million before a federal investigation shut it down. On March 19, 2026, all eleven defendants — Chakrian, Moradians, Hekimyan, Ross Tarkhan, Tigran Hovanesian, Vardevaryan, Higdon, Spangler, Victor Lossi, Marine Sarkisian, and Borjas — were arrested following a grand jury indictment, facing charges that include aggravated identity theft and conspiracy to commit money laundering, after an investigation by the FBI, IRS Criminal Investigation, the U.S. Postal Inspection Service, the Los Angeles County Sheriff's Department, and the Glendale Police Department. First Assistant U.S. Attorney Bill Essayli said, "There is no shortage of massive fraud occurring within California. Today's operation represents one of many sophisticated schemes used by criminals." Elderly homeowners — especially those who own their home free and clear — are advised to periodically pull their own credit report and check county recorder records for any lien, deed, or loan they did not apply for, since a paid-off house generates no monthly statement that would otherwise reveal a fraudulent loan being secretly placed against it.`,
    categorySlug: 'mortgage-foreclosure-scams',
    alertLevel: 'high',
    sources: ["U.S. Attorney's Office for the Central District of California", 'IRS Criminal Investigation', 'CBS Los Angeles'],
    sourceUrl: 'https://www.justice.gov/usao-cdca/pr/2-foreign-nationals-among-11-arrested-charges-they-used-stolen-identities-fraudulently',
    country: 'US',
    state: 'CA',
});

UsAF.push({
    name: `Anchorage Pandemic Relief Fraud (Peter Igwacho)`,
    slug: 'alaska-anchorage-igwacho-ppp-eidl-fraud',
    description: `Peter Igwacho, a 65-year-old Cameroonian national living in Anchorage, filed at least five fraudulent applications between April 2020 and October 2021 seeking pandemic-relief money through the Paycheck Protection Program and the Small Business Administration's Economic Injury Disaster Loan program, falsely claiming a sole proprietorship had employees and revenue it never actually had. After the SBA and participating lenders approved the applications based on his self-certified paperwork, Igwacho spent the more than $172,000 he received on personal expenses rather than payroll, rent, or any other pandemic-related business cost the programs were meant to cover. A federal grand jury in Portland — where the case was prosecuted because of how the investigation was assigned — indicted Igwacho on wire fraud charges in July 2024, and a jury convicted him on all three counts on August 21, 2025 following a three-day trial. On February 26, 2026, a U.S. District Judge sentenced him to 21 months in federal prison plus three years of supervised release and ordered him to pay $182,225.15 in restitution. The Small Business Administration Office of Inspector General and the Treasury Inspector General for Tax Administration, which investigated the case together, noted it as part of the ongoing COVID-19 Fraud Enforcement Task Force's effort to claw back pandemic relief obtained through self-certified applications that were never cross-checked against real payroll or revenue records until years later. The case is a reminder that pandemic-program fraud prosecutions are still actively working through the courts years after the money went out the door, and that a business's self-reported figures on a relief application can and do get compared against actual state and federal wage and tax records long after the funds are spent.`,
    categorySlug: 'public-benefits-fraud',
    alertLevel: 'medium',
    sources: ['U.S. Small Business Administration', 'U.S. Attorney\'s Office for the District of Oregon', 'Oregon Business Report'],
    sourceUrl: 'https://www.sba.gov/article/2026/02/26/alaska-resident-sentenced-federal-prison-wire-fraud',
    country: 'US',
    state: 'AK',
});

UsAF.push({
    name: `Cornerstone Restoration Fire-Repair Contractor Fraud (Thomas and DiNetta Kerfoot)`,
    slug: 'delaware-cornerstone-restoration-kerfoot-fire-repair-fraud',
    description: `Donna Brustman, then 75, lost her longtime family home near Newark, Delaware to a fire and, on her insurance company's own recommendation, signed a contract on December 7, 2022 with Cornerstone Restoration — a Maryland-based company owned by Thomas and DiNetta Kerfoot — to rebuild it using her $262,225 insurance payout. She paid an initial $87,408 and, over the following months, additional payments totaling roughly $298,000, but work stalled almost immediately: Brustman would drive by to find the same overflowing dumpster sitting untouched out front, her calls to DiNetta Kerfoot went unreturned, and the promised September 2023 completion date came and went with little to no progress. What work the Kerfoots did complete reportedly drew more code violations than any other property in New Castle County history. Delaware State Police arrested the Kerfoots in August 2024, but Delaware's Department of Justice dropped the charges that November; a second Cornerstone Restoration client, Greenville attorney Monica Ayres, separately paid roughly $73,000 upfront after an June 2023 house fire and received no completed work either, and New Castle County Police filed fresh charges against the Kerfoots in March 2025 that were still moving through the courts as of that spring, with a preliminary hearing held in May 2025. Delaware reporting on the case identified several other 2025 arrests of home-improvement contractors who collected large upfront payments — in one case more than $1 million from six customers — without finishing the promised work, prompting state lawmakers to move a home-improvement fraud bill through committee. Homeowners rebuilding after a fire or storm should resist a contractor's request for large upfront payments, tie every payment to a specific, inspected stage of completed work, get a second opinion before signing with whichever contractor an insurance company happens to recommend, and check with New Castle County or their local building department for open code violations on an active job before paying anything further.`,
    categorySlug: 'home-improvement-solar',
    alertLevel: 'high',
    sources: ['Spotlight Delaware', 'Newark Post'],
    sourceUrl: 'https://spotlightdelaware.org/2025/04/02/home-improvement-fraud-cases/',
    country: 'US',
    state: 'DE',
});

UsAF.push({
    name: `Fraudulent Colorado Business Registrations Fueling International Scam Networks`,
    slug: 'colorado-fraudulent-business-registration-scam-network-crackdown',
    description: `Colorado Attorney General Phil Weiser announced on May 21, 2026 that his office was pursuing lawsuits to dissolve thousands of Colorado businesses that investigators say were registered using false information, unauthorized home addresses, and virtual mailboxes specifically to lend a veneer of legitimacy to overseas fraud operations. Because a Colorado "certificate of good standing" is a real, checkable government record, scammers used these bogus registrations to reassure victims that the cryptocurrency platform, investment fund, or online storefront they were dealing with was a real, registered Colorado company — one senior lost more than $100,000 in a cryptocurrency investment scam tied to a registrant called Neex LLC, which impersonated a legitimate investment website, while a family in Cripple Creek discovered 370 businesses had been registered to their home address without their knowledge or consent, and a registered agent called Garrettforu LLC was tied to filings for more than 300 fraudulent entities. Investigators linked the network, which also included registrants named Xinbi Co., Ltd. and several other shell entities, to cryptocurrency scams, romance scams, and online retail fraud run out of China and Southeast Asia, and the Attorney General's office said it was working with web-hosting platforms to take down affiliated fraudulent business websites in addition to filing dissolution actions. "These scams succeed because they manufacture trust," Weiser said. "Fraudsters exploited Colorado business registrations to make their operations appear legitimate and convince consumers to hand over their money." Consumers considering an unfamiliar investment platform, crypto exchange, or online seller are advised not to treat a state business registration or "good standing" certificate alone as proof of legitimacy — it confirms only that paperwork was filed, not that the people behind it are who they claim to be — and to independently verify a company's physical presence, ownership, and regulatory registrations (through FINRA BrokerCheck or the SEC's EDGAR database for anything investment-related) before sending money.`,
    categorySlug: 'cryptocurrency-scams',
    alertLevel: 'high',
    sources: ["Colorado Attorney General's Office", 'ColoradoBiz Magazine'],
    sourceUrl: 'https://coag.gov/press-releases/weiser-launches-crackdown-on-fraudulent-colorado-businesses/',
    country: 'US',
    state: 'CO',
});

UsAF.push({
    name: 'Arkansas Small Business Phishing, Fake-Invoice, and Impersonation Scam Alert',
    slug: 'arkansas-small-business-phishing-invoice-impersonation-alert',
    description: `Arkansas Attorney General Tim Griffin issued a consumer alert on June 9, 2025 warning that scammers are increasingly targeting small businesses rather than just individual consumers, and walked through five schemes his office was fielding complaints about: phishing calls, texts, and emails that impersonate a trusted contact to harvest login credentials and company data, which the alert called "a serious threat of identity theft, often disguised as communication from someone you might know"; tech-support scams that spoof caller ID to look like a legitimate software vendor before talking an employee into handing over remote access to a work computer; fake invoices billed for products or services a business never ordered, aimed at accounts-payable staff who pay first and ask questions later; business email compromise, in which a fraudster registers a lookalike domain or hijacks a real vendor's inbox to send an invoice that appears to come from an actual supplier, banking on the fact that "email addresses can be deceptively altered by just one letter"; and business impersonation, where scammers clone a real company's website to intercept customer payments and steal customer data. Griffin's office recommended that businesses train staff to verify any unusual payment, credential, or gift-card request through a second communication channel — a phone call to a number already on file, never one provided in the suspicious message itself — keep antivirus software and staff training current, and report suspected scams to the Arkansas Attorney General's office, the FTC, or the FBI's Internet Crime Complaint Center (IC3).`,
    categorySlug: 'business-email-compromise',
    alertLevel: 'medium',
    sources: ['Arkansas Attorney General (Tim Griffin)'],
    sourceUrl: 'https://arkansasag.gov/news-release/consumer-alert-scammers-are-targeting-small-businesses-in-arkansas/',
    country: 'US',
    state: 'AR',
});

UsAF.push({
    name: `Florida Grandparent Scam Ring's Fake "Hit-and-Run" Injury Escalation`,
    slug: 'florida-grandparent-scam-ring-fake-hit-and-run-escalation',
    description: `Florida Attorney General Ashley Moody's Office of Statewide Prosecution announced on June 24, 2024 the arrest of six people — Jairo Izquierdo, Gennesis Castro, Wendy Angelina Ortiz, Ada Tido, Wandy Castro, and Olfa Cornielle — accused of running a "grandparent scam" that stole nearly $250,000 from elderly victims across Brevard, Broward, Lee, Miami-Dade, Orange, Palm Beach, and Sarasota counties. Callers posing as attorneys or other legal representatives told victims a grandchild had struck a pregnant woman with a car and needed bail money immediately, then escalated the fake emergency over a series of follow-up calls — falsely claiming the woman had lost the baby, that a police officer had been hurt, or that she had died — to extract additional payments each time, instructing victims to withdraw cash and hand it to a courier, often an unwitting rideshare driver hired just to make the pickup, rather than telling any other family member what was happening. A Palm Bay victim alone was bled for $54,000 across four separate payments, and a Melbourne victim lost $53,000, with additional victims in Sarasota and Pompano Beach losing tens of thousands more. All six defendants face multiple first-degree felony charges, including organized scheme to defraud, grand theft, and criminal use of personal identification. "These fraudsters know that most grandparents would do anything to help a grandchild in need," Moody said, adding that the ring used "fear and family to extort Florida seniors" out of nearly a quarter of a million dollars. Because this scheme relies on urgency and secrecy — and because the fabricated emergency can be escalated indefinitely with new demands — anyone who receives a call like this should hang up and independently call the grandchild, or another family member, at a number already saved in their phone before sending a single dollar, no matter how convincing the caller sounds or how many follow-up calls pile on additional charges.`,
    categorySlug: 'grandparent-scams',
    alertLevel: 'high',
    sources: ['Florida Attorney General (Ashley Moody), Office of Statewide Prosecution', 'CBS12 News', 'NBC6 South Florida'],
    sourceUrl: 'https://www.myfloridalegal.com/newsrelease/ag-moody-announces-arrest-six-fraudsters-stealing-nearly-250000-seniors-through',
    country: 'US',
    state: 'FL',
});

UsAF.push({
    name: 'March 2025 Storm Home-Repair Fraud and Price-Gouging Warning',
    slug: 'alabama-march-2025-storm-repair-fraud-price-gouging',
    description: `After tornadoes and severe storms tore through 52 of Alabama's 67 counties in mid-March 2025, prompting Governor Kay Ivey to declare a state of emergency effective 2:00 p.m. on March 14, Attorney General Steve Marshall warned on March 17 that unlicensed, often out-of-town contractors and price gougers tend to follow disaster survivors home looking to profit off the damage. Alabama's price-gouging law activates automatically once a state of emergency is declared, and under it a price 25 percent or more above what was charged for the same good or service in the same area over the prior 30 days is a presumptive violation. Marshall and the Home Builders Licensure Board urged storm victims to ask to see a contractor's state builder's license before hiring — and to verify it by calling the Board at 1-800-304-0853 — to get a written contract listing the full scope, timeline, and total cost of the job, to ask for proof of workers' compensation and liability insurance, and to never pay in full or make a large down payment before work is finished. "We must remain vigilant against those who may try to exploit the goodwill of our community and scam those in distress," Marshall said, encouraging residents in affected counties to report suspected fraud or price gouging to the Attorney General's Consumer Interest Division at 1-800-392-5658.`,
    categorySlug: 'home-improvement-solar',
    alertLevel: 'high',
    sources: ["Alabama Attorney General's Office", 'Alabama Home Builders Licensure Board'],
    sourceUrl: 'https://www.alabamaag.gov/alabama-attorney-general-marshall-warns-storm-emergency-declarations-activate-price-gouging-protections/',
    country: 'US',
    state: 'AL',
});

UsAF.push({
    name: 'Copied-Listing Rental Scam Consumer Alert',
    slug: 'arizona-copied-listing-rental-scam-alert',
    description: `Arizona Attorney General Kris Mayes issued a consumer alert on May 14, 2025 warning renters and homebuyers to watch for fraudsters who either invent fake property listings outright or copy the photos and description from a real, legitimately listed property and repost them at an unusually low price to lure applicants. "Housing is a basic human need and, unfortunately, some fraudsters prey upon that need," Mayes' office said, describing how scammers pressure prospective renters to wire money, pay by gift card, or send funds through a peer-to-peer payment app before ever touring the unit in person, and in some cases use the fake listing to harvest an applicant's Social Security number and banking details under the guise of a rental application. The alert urges consumers to be suspicious of a price well below comparable properties in the area, to independently verify the address exists and matches the listing photos — including by driving by in person — and to avoid any landlord or agent who refuses phone calls and will communicate only by text. Even after viewing a unit, the office recommends getting every fee in writing, reading the full lease before signing anything with blank spaces left in it, and never handing over a security deposit until the signed lease is in hand. Arizonans who believe they've encountered a rental scam can file a complaint with the Attorney General's Office at (602) 542-5763 in Phoenix, (520) 628-6648 in Tucson, or (800) 352-8431 elsewhere in the state.`,
    categorySlug: 'rental-housing',
    alertLevel: 'high',
    sources: ["Arizona Attorney General's Office"],
    sourceUrl: 'https://www.azag.gov/press-release/attorney-general-mayes-warns-consumers-about-rental-scams',
    country: 'US',
    state: 'AZ',
});

UsAF.push({
    name: 'Fake Tax-Relief Company Impersonation Scam',
    slug: 'alaska-fake-tax-relief-company-impersonation-scam',
    description: `The Better Business Bureau warned Alaskans in late January 2026 that scammers are impersonating real, legitimately registered tax-relief and tax-preparation businesses — borrowing names like "America Tax Consultant" or "U.S. Tax Services" — to sound credible when they call, leave voicemails, or send texts claiming to represent an "IRS-authorized" debt-relief program. The callers tell the target they qualify for a new tax-forgiveness program or warn of an unresolved tax debt that must be settled immediately, then pressure them to pay a "processing" or "settlement" fee by cryptocurrency, wire transfer, or prepaid gift card — payment methods the real IRS never asks for. The BBB's Scam Tracker had logged roughly $6 million in attempted losses nationwide over the prior twelve months, including eight reports from Alaskans with a combined attempted loss of about $10,000. "Don't send money when you're under pressure," BBB spokesperson Cameron Nakashima said, urging anyone contacted this way to hang up, look up the company independently on BBB.org, and call the IRS directly at 1-800-366-4484 to confirm whether any debt or program actually exists, since the real IRS always initiates contact by mail rather than by phone, text, or a surprise voicemail.`,
    categorySlug: 'tax-scams',
    alertLevel: 'medium',
    sources: ['Better Business Bureau (BBB) Scam Tracker', "Alaska's News Source"],
    sourceUrl: 'https://www.alaskasnewssource.com/2026/01/29/watch-out-scammers-are-using-real-tax-company-names-steal-your-money-bbb-says/',
    country: 'US',
    state: 'AK',
});

UsAF.push({
    name: 'Springdale Tornado-Repair Contractor Fraud (Austin Lamb)',
    slug: 'arkansas-springdale-lamb-tornado-repair-contractor-fraud',
    description: `Austin Lamb, doing business as Lamb Enterprises (also advertised as "Lamb and Sons") in Springdale, Arkansas, was arrested in Bentonville on March 19, 2025 on three counts of theft of property by deception after collecting $102,717.91 from three households seeking repairs following the May 26, 2024 tornado and then never performing the work. Victims Ken Swindle ($36,897.74), Rene Miranda ($33,820.17), and Doyl and Jeanette Strickert ($32,000) each paid Lamb after he pitched himself as a contractor who could handle their storm damage, but bank records showed the money went into his personal account and was spent at restaurants, Best Buy, O'Reilly Auto Parts, and on Apple products rather than on materials or labor. Investigators found Lamb's actual state license was the most restrictive tier issued by the Arkansas Contractor Licensing Board — residential roofing jobs under $50,000 only — meaning he was never authorized to take on the larger, multi-trade repair work he promised. "We were easy targets, or, at least, I was an easy target. I was so desperate to get a contractor to start working," Swindle told reporters. Because Lamb was already a registered sex offender serving a 10-year probation term, Washington County prosecutors also moved to revoke his probation over the new allegations. Homeowners hiring storm-repair contractors should verify a contractor's actual license class and dollar-amount limit with the Arkansas Contractor Licensing Board before paying anything, get a written contract with a full scope of work, and avoid paying the bulk of a job upfront.`,
    categorySlug: 'home-improvement-solar',
    alertLevel: 'high',
    sources: ['Northwest Arkansas Democrat-Gazette', 'NWA Homepage (KNWA/KFTA)'],
    sourceUrl: 'https://www.nwaonline.com/news/2025/mar/21/contractor-accused-of-taking-more-than-100000/',
    country: 'US',
    state: 'AR',
});

UsAF.push({
    name: 'SNAP EBT Card Skimming and Benefit-Theft Phishing Scam',
    slug: 'delaware-snap-ebt-skimming-benefit-theft-phishing-scam',
    description: `Delaware's Department of Health and Social Services (DHSS) warned SNAP recipients on June 9, 2026 of a rise in EBT card skimming and benefit theft, urging clients to lock their cards and change PINs after seeing more Delawareans report stolen food-assistance funds. Thieves plant card-skimming devices on point-of-sale terminals and ATMs to capture card numbers and PINs, then clone the cards and drain benefits in purchases that can occur across multiple states within minutes; a related wave of phishing calls and texts falsely claims a recipient's EBT card has been locked or that benefits are about to stop, tricking them into reading off their card number or PIN. Delaware saw 2,154 theft claims in 2024, with $956,000-plus ultimately replaced under a temporary federal reimbursement program, but that federal authority to reimburse stolen SNAP benefits expired in December 2024 and Congress has not renewed it — meaning the 1,132 thefts totaling $166,308 reported in Delaware through 2025 largely cannot be recovered. "Protecting SNAP benefits is more important than ever. We are seeing more Delawareans report stolen benefits and taking a few simple steps now can help reduce the risk of fraud," DHSS Secretary Christen Linke Young said. DHSS recommends activating the "Lock My Card Everywhere" feature in the ConnectEBT app or website, using a PIN that isn't a birthdate or simple sequence, never sharing card numbers or PINs with anyone outside the household, and calling EBT Customer Service at 1-800-526-9099 immediately if theft is suspected, followed by DHSS Form 306 to formally report it.`,
    categorySlug: 'public-benefits-fraud',
    alertLevel: 'high',
    sources: ['Delaware Department of Health and Social Services', 'WHYY'],
    sourceUrl: 'https://news.delaware.gov/2026/06/09/dhss-urges-snap-recipients-to-take-action-to-protect-ebt-benefits-from-theft/',
    country: 'US',
    state: 'DE',
});

UsAF.push({
    name: 'Montgomery Medicaid Employee Fraudulent Transportation-Claims Theft (Natalie Colette Lewis)',
    slug: 'alabama-lewis-medicaid-transportation-claims-theft',
    description: `Natalie Colette Lewis, 60, of Montgomery, worked as a Medical Care Benefits Specialist in the Alabama Medicaid Agency's Non-Emergency Transportation Division, where her job was to process reimbursement claims for Medicaid recipients' travel to medical appointments. Between December 2019 and November 2024, Lewis instead submitted 1,631 fraudulent transportation claims for her own son, a Medicaid recipient, for medical appointments that never actually took place, collecting $103,413.26 that she spent on personal expenses rather than passing on to any legitimate transportation provider. The theft was uncovered internally by the Alabama Medicaid Agency, which referred the matter to the Alabama Attorney General's Medicaid Fraud Control Unit for investigation. Lewis pleaded guilty to aggravated theft of property, and Montgomery County Circuit Judge Brooke Reid accepted the plea on August 26, 2025, with sentencing set for October 2, 2025; she faced up to 30 years in prison, a fine of up to $60,000, and forfeiture of her state retirement benefits. "Public service is a responsibility, not a personal financial opportunity," Attorney General Steve Marshall said in announcing the conviction, adding that the Medicaid Fraud Control Unit would continue holding accountable "those who exploit their positions to defraud state programs and steal from Alabama taxpayers." The case is a reminder that Medicaid fraud isn't limited to outside con artists — an insider with legitimate system access can falsify claims for years before detection — and that recipients and their families should keep their own records of medical appointments and transportation used, since those records are often what exposes a mismatch when an agency's internal review catches up.`,
    categorySlug: 'medicare-health-plans',
    alertLevel: 'medium',
    sources: ["Alabama Attorney General's Office", 'The Trussville Tribune'],
    sourceUrl: 'https://www.alabamaag.gov/attorney-general-marshall-announces-conviction-of-former-state-employee-for-the-theft-of-over-100000-from-alabama-medicaid-agency/',
    country: 'US',
    state: 'AL',
});

UsAF.push({
    name: 'Alaska Timeshare Exit Advance-Fee Scheme (Consumer Law Protection / Square One Group)',
    slug: 'alaska-timeshare-exit-advance-fee-scheme',
    description: `Beginning around 2019, a rotating set of companies operating under names including Consumer Law Protection, Consumer Rights Council, Premier Reservations Group, Resort Transfer Group, Square One Development Group, Square One Group, and Timeshare Help Source mailed Alaska timeshare owners deceptive postcards promising a free $250 shopping card and help exiting or renegotiating their timeshare contracts. Owners who called back were invited to sales presentations at Anchorage hotels, where salespeople used scare tactics — falsely warning that maintenance fees would skyrocket and that heirs would be stuck paying them forever — to pressure attendees into signing on the spot and paying large upfront fees, sometimes exceeding $10,000, for an "exit service" that was never actually delivered. Alaska's Attorney General sued the operation's corporate entities and eight individuals — Christopher Carroll, George Reed, Louann Reed, Scott Jackson, Eduardo Balderas, Sherrod Banks, Courtney Kirkpatrick, and Gary Adamson — in June 2022, and on October 4, 2024 an Anchorage Superior Court ordered them to pay a combined $310,000 in civil penalties and $177,349 in restitution to defrauded Alaskans, while banning several defendants from selling goods or services in the state for five years. Attorney General Treg Taylor urged Alaskans to treat unsolicited timeshare-relief offers with "healthy skepticism," since a legitimate exit or resale service does not need to be marketed through a free-dinner postcard and does not require a large fee before any work is done; timeshare owners looking to exit a contract should instead contact their resort directly about a deed-back program or consult a licensed attorney before paying anyone upfront.`,
    categorySlug: 'timeshare-scams',
    alertLevel: 'medium',
    sources: ['Alaska Department of Law, Office of the Attorney General'],
    sourceUrl: 'https://www.law.alaska.gov/press/releases/2024/100424-Timeshare.html',
    country: 'US',
    state: 'AK',
});

UsAF.push({
    name: 'Anchorage Rheumatology Clinic Insurance and Tax Fraud (Claribel and Daniel Tan)',
    slug: 'alaska-anchorage-tan-rheumatology-billing-fraud',
    description: `Dr. Claribel Tan and her husband Daniel Tan ran an Anchorage rheumatology clinic treating conditions like rheumatoid arthritis, osteoarthritis, and psoriatic arthritis from 2005 onward, and for roughly 15 years padded their insurance billings well beyond what patients actually received: prosecutors found the clinic billed for 4,829 units of injectable medication while purchasing only 369, meaning most billed doses were never truly administered — patients were often given expired medication, free drug samples, or a different medication than what was billed, undermining their actual treatment while insurers paid for care that never happened. The scheme generated more than $12.5 million in fraudulent billings to more than ten insurance plans, while the Tans separately evaded more than $4.2 million in taxes by filing false returns for 2014, 2015, and 2017 that overstated the clinic's expenses, and by simply not filing any clinic tax returns at all from 2018 through 2021. A federal grand jury indicted the couple in July 2024; they pleaded guilty in November 2025, and in March 2026 Claribel Tan was sentenced to six and a half years in federal prison plus three years of supervised release, while Daniel Tan received three years of probation, including two years of home confinement. Prosecutors had already seized roughly $10.4 million in proceeds, and the Tans made a $6.3 million payment toward restitution. The case is a reminder that a long-running, legitimate-seeming medical practice can still be running an insurance fraud scheme for years — patients should keep their own records of exactly which medication and dose they received at each visit and compare them against their insurer's explanation-of-benefits statement, since a mismatch between what was actually given and what was billed is often the first sign something is wrong.`,
    categorySlug: 'healthcare-fraud',
    alertLevel: 'medium',
    sources: ["U.S. Attorney's Office, District of Alaska", 'Internal Revenue Service Criminal Investigation', 'Anchorage Daily News'],
    sourceUrl: 'https://www.justice.gov/usao-ak/pr/anchorage-doctor-sentenced-prison-multi-million-dollar-health-care-tax-fraud-schemes',
    country: 'US',
    state: 'AK',
});

UsAF.push({
    name: 'Delaware Bitcoin ATM and Crypto Kiosk Scam Surge',
    slug: 'delaware-bitcoin-atm-crypto-kiosk-scam-surge',
    description: `Delaware Attorney General Kathy Jennings warned on January 9, 2025 that Bitcoin ATM scams were surging nationally — a 1,000% jump in reported losses since 2020, and $110 million in complaints to the FTC in 2023 alone — and cautioned Delawareans about a scheme in which a caller or online contact posing as a government agency, a bank fraud department, or a too-good-to-be-true investment opportunity pressures a victim to withdraw cash immediately and feed it into a nearby cryptocurrency ATM, scanning a QR code or entering a wallet address the scammer supplies; because the machine converts the cash to crypto and sends it straight to the scammer's wallet, the transaction is irreversible within minutes. "Scammers create some urgent justification for you to take cash out of your bank accounts and put it into a Bitcoin ATM," Jennings said. The warning proved prescient: state lawmakers revealed in 2026 that Delaware's Investor Protection Unit had logged 181 cryptocurrency complaints and 255 cryptocurrency-wallet complaints in 2025 alone, totaling $26,893,098 in reported losses, with more than half involving people over 50 — prompting the House Economic Matters Committee to release a bill in June 2026 that would eliminate unregulated cryptocurrency kiosks in Delaware entirely. Anyone contacted out of the blue and told an account or investment can only be "protected" by withdrawing cash and feeding it into a crypto ATM should treat that instruction itself as proof of fraud, hang up, and verify independently with their bank or the agency the caller claims to represent using a number looked up separately, not one the caller provided.`,
    categorySlug: 'cryptocurrency-scams',
    alertLevel: 'high',
    sources: ['Delaware Department of Justice', 'Delaware House Democrats', 'The Defiant'],
    sourceUrl: 'https://news.delaware.gov/2025/01/09/delaware-attorney-general-warns-delawareans-not-to-fall-for-bitcoin-atm-scams/',
    country: 'US',
    state: 'DE',
});

UsAF.push({
    name: 'Delaware 23andMe Genetic Data Breach Bankruptcy Settlement',
    slug: 'delaware-23andme-genetic-data-breach-settlement',
    description: `After a 2023 data breach exposed the genetic and personal data of roughly 6.9 million 23andMe customers worldwide — including ancestry reports, health-risk information, and, for many users, the identities of their genetic relatives — the company filed for bankruptcy in 2025, leaving affected customers with little direct recourse against the company itself. Delaware Attorney General Kathy Jennings joined a coalition of 42 other state attorneys general in pursuing 23andMe's bankruptcy trustee over the breach, announcing on July 14, 2026 a settlement that secured $150 million in allowed claims for the states, though the finite funds remaining in the bankruptcy estate limited actual recovery to $18 million, of which Delaware will receive $159,654 for its Consumer Protection Fund; the settlement runs alongside a separate $46.75 million class-action fund for individual consumers who filed a claim by February 17, 2026. Genetic data is uniquely sensitive because, unlike a password or credit card number, it cannot be changed or reissued once exposed, and it can reveal information about blood relatives who never used the service themselves. Anyone who used 23andMe or a similar consumer genetic-testing service should watch for phishing attempts that reference specific ancestry or health details from the breach — a tactic that makes a scam message look far more credible — and should never pay an unsolicited caller or emailer claiming they can "protect" genetic data or recover a settlement payment on the customer's behalf.`,
    categorySlug: 'identity-theft',
    alertLevel: 'medium',
    sources: ['Delaware Department of Justice'],
    sourceUrl: 'https://news.delaware.gov/2026/07/14/ag-jennings-announces-multistate-settlement-of-bankruptcy-claims-against-23andme-over-genetic-data-breach/',
    country: 'US',
    state: 'DE',
});
